#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was created with NewObject in BeginPlay but stored in a plain raw pointer that is not a UPROPERTY, so the garbage collector could collect the UArenaScoreTracker. The packaged log shows 'LogGarbage: Collecting garbage: 412 objects purged' at 21.05.13, about a minute after start, and the crash at 21.05.27 is EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints() (ArenaScoreTracker.cpp:18) called from AArenaGameMode::OnGoalScored() (ArenaGameMode.cpp) when a goal was scored, i.e. a dangling pointer dereference. Fixed by making ScoreTracker a UPROPERTY TObjectPtr so GC keeps it alive.",
  "no_colors_cause": "The arena palette asset /Game/Data/Palettes/DA_Primary is loaded at runtime by code (LoadObject in AArenaGameMode::BeginPlay) and is not referenced by the cooked map, so with packaging config bCookAll=False and only /Game/Data/Effects listed in DirectoriesToAlwaysCook, the asset was never cooked into the package. The packaged log shows 'LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary' and 'LogArena: Warning: Palette is null, using fallback gray', so the HUD rendered in gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook in Config/DefaultGame.ini."
}
